        "text": "[Тот Брахман —] единая суть высшего блаженства, высший, самосветящийся Свет, чья природа свободна от [всякой] двойственности (авикальпа), в котором растворены все страдания; Он есть то, что должно быть познано, умиротворённое, познаваемое лишь самим собой."
