        "type": "verse",
        "number": "85",
        "sanskrit": "[अथ रसस्य स्थानान्तरगतवर्णनम् — строфа сильно повреждена] प्रथमे रजसि स्नाता हयारूढा सुलंकृता । योत्तमाना वधूं दृष्ट्वा जिष्णुस्तु कूपगो रसः ॥ ८५॥",
        "text": "Текст этой строфы дошёл в источнике настолько испорченным, что уверенно восстановить его содержание невозможно. Судя по сохранившимся словам, речь идёт о некой невесте (вадху), впервые омывшейся [после первой менструации], нарядно убранной и восседающей на коне, — и о некоем притяжении ртути, пребывающей в колодце, к этой сцене. Дальнейшие детали (кто конкретно действует и в каком смысле) в данном фрагменте не поддаются проверке; перевод не приводится во избежание домысливания содержания."
