        "text": "Слюда в сочетании с виданга и трикату, принимаемая с ними, побеждает: анемию/бледность, расстройство грахани, кожные болезни, одышку, мочевые расстройства, отсутствие аппетита, желтуху, слабость пищеварительного огня и боли в животе, а посредством иных сочетаний — и все остальные недуги."
