        "text": "Ишвара сказал: «Некогда, о богиня, на Швета-двипе, украшенном всеми драгоценностями, дарующем все желания, на прекрасном берегу Молочного океана, — в окружении лучших видьядхари, женщин-йогинь, сиддха-женщин и апсар…»"
