        "text": "Жемчуг лёгок, охлаждающ, сладок на вкус, придаёт блеск (коже), укрепляет и питает пищеварительный огонь, устраняет яд, обладает вяжуще-очищающим (или «раскалывающим») действием, уничтожает болезни; рождается он из океана, из раковины-жемчужницы. [Одна деталь стиха — фраза о «сиянии» и о некоем недуге, названном в источнике «пакшируджа» («птичья хворь»?) — восстанавливается неуверенно: сам комментарий здесь тоже тёмен и не даёт ясного пояснения, поэтому это место переведено с осторожностью и не гарантируется как точное.]"
