        "text": "Считается, что жемчуг устраняет Капху, Питту, чахотку (кшая) и одышку, кашель, удушье и слабость пищеварительного огня, укрепляет тело, полезен для тканей (дхату), продлевает жизнь и уничтожает — согласно этому стиху — двенадцать различных недугов."
