        "text": "Восемь раз прокаливают в сухих лесных лотосах (в качестве топлива), а затем ещё сто раз погружают в очищенную ртуть — так алмаз непременно превращается в золу (бхасму) и становится «лёгким как вода» (то есть плавающим на воде)."
