        "text": "Растёртый таким образом алмаз, немного усиленный (добавками), двадцать раз подряд обрабатывают, скатывая с сущностью (саттвой) «кхарабхунага» (свинца/олова) — так надёжно получают шарики того же качества, которые можно применять в ртутных и иных препаратах."
