        "text": "[Стих даёт числовую пропись состава, но конкретные числительные и названия компонентов сильно повреждены OCR, поэтому переведён приблизительно.] Приблизительный смысл: измельчённая зола алмаза (ваджра-бхасма) берётся в тридцать частей; к ней добавляется золото в некоей доле; серебро — в кратном количестве; медь — в восемь частей; тапьяка — в четверть части; вайкранта — в восьмикратном количестве; и всё это в определённой пропорции добавляется к ртути (расе) — так составляется препарат, называемый «шад-гуна-раса» («шестикачественная ртуть»), обеспечивающий все шесть достоинств. Комментарий приводит конкретную рецептуру (алмазная зола — 30 частей, золотая зола — 16, серебряная зола — 8 и т.д.), но из-за состояния источника точные числа не гарантируются."
