        "text": "На сердцевину [лотоса] следует поставить железную ступку (кхалва), покрытую золотом; в неё [поместить] расараджу (ртуть) весом в сто пал (мера веса), или пятьдесят, или двадцать пять, и почитать [её] подобно расалинге."
