        "text": "[Приведены семенные слоги пятисложной мантры; точное их звучание восстановить с уверенностью не удалось.] Этой коренной мантрой следует там почтить Бхайраву; затем нужно провозгласить имена всех сиддхов (совершенных адептов) ртутного делания."
